require"active_support/core_ext/string/multibyte";require"active_support/i18n";module ActiveSupport;module Inflector;ALLOWED_ENCODINGS_FOR_TRANSLITERATE=[Encoding::UTF_8,Encoding::US_ASCII,Encoding::GB18030].freeze;def transliterate(string,replacement="?",locale:nil)raise ArgumentError,"Can only transliterate strings. Received #{string.class.name}" unless string.is_a?(String);raise ArgumentError,"Cannot transliterate strings with #{string.encoding} encoding" unless ALLOWED_ENCODINGS_FOR_TRANSLITERATE.include?(string.encoding);return string.dup if string.ascii_only?;string=string.dup if string.frozen?;input_encoding=string.encoding;string.force_encoding(Encoding::UTF_8) if string.encoding==Encoding::US_ASCII;string.encode!(Encoding::UTF_8,invalid: :replace,undef: :replace) if string.encoding==Encoding::GB18030;transliterated=I18n.transliterate(ActiveSupport::Multibyte::Unicode.tidy_bytes(string).unicode_normalize(:nfc),replacement:replacement,locale:locale);transliterated.encode!(input_encoding,invalid: :replace,undef: :replace) if input_encoding!=transliterated.encoding;transliterated;end;def parameterize(string,separator:"-",preserve_case:false,locale:nil)parameterized_string=transliterate(string,locale:locale);parameterized_string.gsub!(/[^a-z0-9\-_]+/i,separator);unless separator.nil?||separator.empty?;if separator=="-";re_duplicate_separator=/-{2,}/;re_leading_trailing_separator=/^-|-$/i;else re_sep=Regexp.escape(separator);re_duplicate_separator=/#{re_sep}{2,}/;re_leading_trailing_separator=/^#{re_sep}|#{re_sep}$/i;end;parameterized_string.gsub!(re_duplicate_separator,separator);parameterized_string.gsub!(re_leading_trailing_separator,"");end;parameterized_string.downcase! unless preserve_case;parameterized_string;end;end;end
